import{_ as a,o,c as i,ag as l}from"./chunks/framework.ePeAWSvT.js";const u=JSON.parse('{"title":"声纹识别","description":"","frontmatter":{},"headers":[],"relativePath":"voice/voiceprint.md","filePath":"voice/voiceprint.md","lastUpdated":null}'),e={name:"voice/voiceprint.md"};function r(n,t,s,d,c,h){return o(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="声纹识别" tabindex="-1">声纹识别 <a class="header-anchor" href="#声纹识别" aria-label="Permalink to &quot;声纹识别&quot;">​</a></h1><blockquote><p>录音转写自动标记「你说的话」，多人对话一目了然</p></blockquote><p>录入你的声音后，AI 即可在录音笔记中自动识别并标记你的发言。多人会议、访谈对话，每句话都能对号入座，回顾整理更高效。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ul><li><strong>团队会议</strong>：多人讨论时自动区分每位发言者，快速定位自己说了什么</li><li><strong>采访访谈</strong>：记者与受访者对话清晰分离，整理稿件效率翻倍</li><li><strong>课堂互动</strong>：师生问答场景中，轻松区分老师讲解与自己的提问发言</li><li><strong>头脑风暴</strong>：多人创意碰撞，自己的观点都被准确归属，不再混淆</li><li><strong>一对一沟通</strong>：导师辅导、客户沟通等场景，双方发言一目了然</li></ul><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><ul><li><strong>声纹录入</strong>：录入一段你的声音，AI 即可学习并记住你的声纹特征</li><li><strong>自动标记</strong>：录音转写时，AI 自动将你的发言标记为你的名字，其他人显示为「说话人 2」「说话人 3」等</li><li><strong>多人区分</strong>：即使多人同时参与对话，也能智能区分不同说话人</li><li><strong>无感使用</strong>：声纹识别在后台自动运行，录音和转写流程无需任何额外操作</li></ul><h2 id="使用额度" tabindex="-1">使用额度 <a class="header-anchor" href="#使用额度" aria-label="Permalink to &quot;使用额度&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用户类型</th><th>说明</th></tr></thead><tbody><tr><td>会员用户</td><td>声纹识别为会员专属功能，开通会员后即可自动识别</td></tr><tr><td>免费用户</td><td>可免费试用 10 次（即 10 条录音笔记可进行声纹识别）</td></tr></tbody></table><h2 id="如何使用" tabindex="-1">如何使用 <a class="header-anchor" href="#如何使用" aria-label="Permalink to &quot;如何使用&quot;">​</a></h2><ol><li>打开 App，首页左上角菜单点头像，进入「我的账号」页面</li><li>在常用操作区域点击「声纹识别」</li><li>进入声纹识别设置页，开启「启用声纹标记」开关</li><li>点击「录入我的声音」，根据提示朗读一段文字，完成声纹采集</li><li>设置完成后，正常使用录音功能即可——AI 会在生成录音笔记时自动匹配声纹</li></ol><div class="tip custom-block"><p class="custom-block-title">小技巧</p><p>在已有录音笔记中，点「文字记录」tab，点击某个说话人并勾选&quot;同步至我的声纹&quot;，也可以把对应的声音标记为自己。</p></div>',12)])])}const _=a(e,[["render",r]]);export{u as __pageData,_ as default};
